contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        require(putAmount >= 0);
        require(address(this).balance >= putAmount);

        c.Put{value: putAmount}(unlockTime);

        uint minSum = c.MinSum();
        (uint unlock, uint balance) = c.Acc( address(this) );
        uint cBalBefore = address(c).balance;
        bool shouldRevert = balance < minSum || balance < collectAmount || block.timestamp <= unlock;

        bool reverted;
        try c.Collect(collectAmount) { reverted = false; } catch { reverted = true; }

        (uint unlockAfter, uint balanceAfter) = c.Acc( address(this) );
        uint cBalAfter = address(c).balance;

        if (shouldRevert) {
            assert(reverted && balanceAfter == balance && cBalAfter == cBalBefore);
        } else {
            assert(!reverted && balanceAfter == balance - collectAmount && cBalAfter == cBalBefore - collectAmount);
        }
    }

    receive() external payable {}
}

