contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "not enough balance to fund Put");

        // Establish the caller's account via Put. Unlock time is either the supplied
        // value if it is in the future, or block.timestamp (must wait at least 1s
        // for block.timestamp to advance before attempting Collect).
        c.Put{value: putAmount}(unlockTime);

        // Read the state after Put through public getters.
        (uint beforeUnlockTime, uint beforeBalance) = c.Acc( address(this) );
        uint minSum = c.MinSum();

        // Attempt Collect from the same account.
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the state after Collect.
        (uint afterUnlockTime, uint afterBalance) = c.Acc( address(this) );

        // General rule: Collect succeeds exactly when the caller's pre-balance is
        // >= MinSum and >= collectAmount, and block.timestamp > unlockTime.
        // Otherwise it must revert. On success the balance decreases by exactly
        // collectAmount and unlockTime is unchanged.
        bool successCondition = beforeBalance >= minSum
            && beforeBalance >= collectAmount
            && beforeUnlockTime < block.timestamp;

        if (successCondition) {
            assert(!reverted);
            assert(afterBalance == beforeBalance - collectAmount);
            assert(afterUnlockTime == beforeUnlockTime);
        } else {
            assert(reverted);
            assert(afterBalance == beforeBalance);
            assert(afterUnlockTime == beforeUnlockTime);
        }
    }

    receive() external payable {}
}

