contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint _am) public payable {
        // If _am is 0, the condition acc.balance >= _am is trivially true, but the
        // rule tested is the general non-zero guard: for _am > 0, Collect must
        // revert when the caller's balance is below MinSum or the unlock time
        // has not passed. To make the test meaningful, we use a fresh call with
        // _am > 0 and observe the revert behavior.
        require(_am > 0, "amount must be > 0");

        // Read the caller's (this contract's) Holder state as seen through the
        // public getter `Acc`. On a fresh c, balance == 0 and unlockTime == 0.
        (uint unlockTime, uint balance) = c.Acc(address(this));

        // Since _am > 0 and balance == 0, balance >= MinSum is false, so
        // Collect must revert. We try to determine this behavior by calling
        // Collect; the call is a top-level statement.
        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: because the caller has no deposited balance (balance = 0),
        // and MinSum is at least 1 ether (non-zero), and _am > 0, the condition
        // for Collect to proceed cannot be satisfied, so it must revert.
        // This rule would be broken by a faulty version that allows
        // unauthorized withdrawal without a sufficient balance.
        assert(reverted == (balance < c.MinSum() || balance < _am || block.timestamp <= unlockTime));
    }

    receive() external payable {}
}

