        c.Put{value: deposit}(0);

        (uint unlockTime, uint balanceBefore) = c.Acc(address(this));
        uint minSum = c.MinSum();

        bool reverted;
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
