import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    C c;

    function setUp() public {
        c = new C(address(new Log()));
    }

    function _run(uint256 unlockTime, uint256 topUp, uint256 am) internal {
        topUp = bound(topUp, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(topUp > 0);
        vm.assume(address(this).balance >= topUp);
        try c.Put{value: topUp}(unlockTime) {} catch { return; }
        uint256 u0;
        uint256 b0;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { u0 = __r0; b0 = __r1; } catch { return; }
        uint256 minSum;
        try c.MinSum() returns (uint256 __r) { minSum = __r; } catch { return; }
        bool eligible = (b0 >= minSum) && (b0 >= am) && (block.timestamp > u0);
        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }
        uint256 u1;
        uint256 b1;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { u1 = __r0; b1 = __r1; } catch { return; }
        assertTrue(eligible || (b1 == b0));
    }

    function testFuzz_run(uint256 unlockTime, uint256 topUp, uint256 am) public {
        _run(unlockTime, topUp, am);
    }

    receive() external payable {}
}

